const TOOL_ID = 'mas-rechisha';
const P = 'jt7';

const EXAMPLE = { price: 2650000, date: '2026-10-13', track: 'single', contractor: false, delivery: '', aliyah: '', lawyerPct: 0.5, brokerPct: 2, other: 0 };
const PRICE_POINTS = [1500000, 2000000, 2500000, 3000000, 4000000, 6000000, 8000000];

